 fields=line.split(); mount=fields[4].replace(\"\\\\040\",\" \");
 if p==mount or p.startswith(mount.rstrip(\"/\")+\"/\"): mounts.append((len(mount),line.strip()))
result[\"covering_mount\"]=max(mounts)[1] if mounts else None; result[\"sha256_before\"]=before; result[\"sha256_after\"]=hashlib.sha256(open(p,\"rb\").read()).hexdigest(); result[\"unchanged\"]=result[\"sha256_before\"]==result[\"sha256_after\"]; print(json.dumps(result))'"

